-- =========================================================
-- 인테리어 소품 100종 (선실 방꾸미기, 사용자 제공 일러스트 10장 크롭)
-- =========================================================
on conflict (sku) do nothing;


-- =========================================================
-- 인테리어 소품을 이미 생성된 모든 가족(household)의 가방(inventory_items)에 지급
-- 신규 가족은 onboarding/complete 라우트에서 동일하게 지급됨
-- =========================================================
select h.id, c.id, 1
from public.households h
cross join public.item_catalog c
where c.subcategory = 'interior_pack'
  and not exists (
    select 1 from public.inventory_items i
    where i.household_id = h.id and i.catalog_item_id = c.id
  );
